export function shippingCost(weightKg: number, ratePerKg: number): number {
  const rawCents = Math.round(weightKg * ratePerKg * 100);
  const taxedCents = Math.round(rawCents * (1 + TAX_RATE));
  return taxedCents / 100;
}

const TAX_RATE = 0.21;

